select post.id, 'en', '30 Essential Lithuanian Phrases for Everyday Life in Lithuania', 'The 30 Lithuanian phrases you will use every day — greetings, polite words, shopping, directions, cafés and emergencies — with English meanings and simple pronunciation tips.',
       '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You do not need fluent Lithuanian to make daily life easier — and nicer. A few well-chosen phrases go a long way in shops, cafés, at work and with your neighbours. People notice and appreciate the effort."}]},{"type":"paragraph","content":[{"type":"text","text":"Here are 30 phrases grouped by situation. You can hear every key word with native audio in our free "},{"type":"text","text":"vocabulary list","marks":[{"type":"link","attrs":{"href":"/vocabulary","target":null,"rel":"noopener noreferrer"}}]},{"type":"text","text":" and practise them with "},{"type":"text","text":"flashcards","marks":[{"type":"link","attrs":{"href":"/flashcards","target":null,"rel":"noopener noreferrer"}}]},{"type":"text","text":". New to the letters? Read our "},{"type":"text","text":"Lithuanian alphabet and pronunciation guide","marks":[{"type":"link","attrs":{"href":"/blog/lithuanian-alphabet-pronunciation-guide","target":null,"rel":"noopener noreferrer"}}]},{"type":"text","text":" first."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Greetings and goodbyes"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Labas!","marks":[{"type":"bold"}]},{"type":"text","text":" — Hello! (everyday, informal)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sveiki!","marks":[{"type":"bold"}]},{"type":"text","text":" — Hello! (polite, or to several people)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Laba diena!","marks":[{"type":"bold"}]},{"type":"text","text":" — Good day! / Good afternoon!"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Labas rytas!","marks":[{"type":"bold"}]},{"type":"text","text":" — Good morning!"}]}]},{"type":"listItem","content":[{"type":"paragraph","c