"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mano vardas…","marks":[{"type":"bold"}]},{"type":"text","text":" — My name is…"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Koks jūsų vardas?","marks":[{"type":"bold"}]},{"type":"text","text":" — What is your name? (polite)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Aš esu iš Bangladešo / Indijos / Uzbekistano.","marks":[{"type":"bold"}]},{"type":"text","text":" — I am from Bangladesh / India / Uzbekistan."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Malonu susipažinti.","marks":[{"type":"bold"}]},{"type":"text","text":" — Nice to meet you."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"When you don''t understand"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Aš nesuprantu.","marks":[{"type":"bold"}]},{"type":"text","text":" — I don''t understand."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Gal galite pakartoti?","marks":[{"type":"bold"}]},{"type":"text","text":" — Could you repeat that?"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prašau kalbėti lėčiau.","marks":[{"type":"bold"}]},{"type":"text","text":" — Please speak more slowly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ar kalbate angliškai?","marks":[{"type":"bold"}]},{"type":"text","text":" — Do you speak English?"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Shopping and paying"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kiek kainuoja?","marks":[{"type":"bold"}]},{"type":"text","te